<script setup>
defineProps({attempt:Object});
const labels={started:'Begonnen',completed:'Abgeschlossen',approved:'Fachlich freigegeben'};
</script>
<template><article class="rounded-xl border bg-white p-5"><div class="flex flex-wrap justify-between gap-2"><h3 class="font-semibold">{{attempt.profile?.name}} · {{attempt.tested_on?.slice(0,10)}}</h3><span class="text-sm">{{labels[attempt.status]}}</span></div><p class="text-xs text-gray-500">Profilversion {{attempt.profile?.version}} · Durchführung {{attempt.id}} · Stand {{attempt.revision}}</p><div v-for="(result,key) in attempt.results" :key="key" class="mt-4 border-t pt-3"><h4 class="font-semibold">{{result.label}}: {{result.points}} / {{result.max}} <span v-if="result.complete">({{result.percent}} %)</span><span v-else class="text-amber-700"> · unvollständig</span><span v-if="result.grade"> · Note {{result.grade}}</span></h4><p v-if="result.below_threshold" class="text-sm text-amber-800">Unter der hinterlegten Hinweisgrenze – Förderbedarf fachlich prüfen.</p><div class="mt-3 grid gap-3 md:grid-cols-2"><div v-for="(label,field) in {observation:'Beobachtungen',assessment:'Einschätzung',support_need:'Förderbedarf',next_steps:'Förderziel / nächste Schritte'}" :key="field"><p class="text-xs font-semibold uppercase text-gray-500">{{label}}</p><p class="whitespace-pre-wrap text-sm">{{attempt.reports?.[key]?.[field] || 'Noch nicht dokumentiert'}}</p></div></div><details class="mt-3 text-sm"><summary class="cursor-pointer text-zbb">Einzelergebnisse</summary><div v-for="item in result.items" :key="item.key" class="mt-2"><p>{{item.label}}: {{item.complete ? item.points : 'unvollständig'}} / {{item.max}}</p><div v-for="child in item.children||[]" :key="child.key" class="ml-4"><p>{{child.label}}: {{child.complete ? child.points : 'unvollständig'}} / {{child.max}}</p><p v-for="leaf in child.children||[]" :key="leaf.key" class="ml-4">{{leaf.label}}: {{leaf.points ?? 'offen'}} / {{leaf.max}}</p></div></div></details></div></article></template>
